{
"css": "/* Booking Section Structure */
#booking-layout {
  border-top: 1px solid #ededf0;
  padding: 20px 0;
}

/* Host Region */
.booking-host {
  margin-bottom: 20px;
}

.booking-host-title {
  font-size: 16px;
  font-weight: 700;
  color: #202024;
  margin: 0 0 4px 0;
  line-height: 1.3;
}

.booking-host-subtitle {
  font-size: 14px;
  color: #60606a;
  margin: 0;
  line-height: 1.5;
}

/* Action Row (Style controls only, layout owned by parent) */
#booking-actions {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
}

/* Favorite Icon Button */
.booking-icon-btn {
  background: transparent;
  border: none;
  padding: 0;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  margin: 0;
  color: #60606a;
  transition: color 0.2s ease, background-color 0.2s ease;
  border-radius: 50%;
}

.booking-icon-btn:hover {
  background-color: #f7f7f9;
  color: #5146d7;
}

.booking-icon-btn:focus-visible {
  outline: 3px solid #5146d7;
  outline-offset: 2px;
}

.booking-icon-btn[aria-pressed="true"] {
  color: #5146d7;
}

.booking-icon-btn img {
  display: block;
  width: 24px;
  height: 24px;
  object-fit: contain;
}

/* Primary Book Button */
#book {
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  height: 52px;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

#book:hover {
  background-color: #4338c4;
}

#book:focus-visible {
  outline: 3px solid #5146d7;
  outline-offset: 2px;
  background-color: #5146d7;
}

#book:active {
  transform: scale(0.98);
}

/* Note */
.booking-note {
  font-size: 14px;
  color: #60606a;
  margin: 12px 0 0 0;
  line-height: 1.6;
  padding-left: 0;
}"
}
